mapper.select:
SELECT *
FROM activity
WHERE id = #{activityId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

SELECT audience_department_ids, contract_version, lifecycle_status, form_version, form_schema, cancelled_at, cancel_reason, publish_status, summary, audience_summary, registration_mode, participant_mode, capacity, capacity_unit, cover_attachment_id, id, title, category, organizer, audience_scope, published_at, location FROM activity WHERE publish_status = 1 AND deleted_at IS NULL
AND category = #{category}
AND lifecycle_status = #{lifecycleStatus}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))
AND (audience_department_ids IS NULL OR JSON_LENGTH(audience_department_ids) = 0) AND (audience_scope IS NULL OR audience_scope = 0 OR (audience_scope & 1) = 1)
AND ( ((audience_department_ids IS NULL OR JSON_LENGTH(audience_department_ids) = 0) AND (audience_scope IS NULL OR audience_scope = 0 OR (audience_scope & 1) = 1)) OR JSON_CONTAINS(audience_department_ids, JSON_QUOTE(#{departmentId})) )
AND (published_at < (SELECT published_at FROM activity WHERE id = #{lastId}) OR (published_at = (SELECT published_at FROM activity WHERE id = #{lastId}) AND id < #{lastId}))
ORDER BY published_at DESC, id DESC LIMIT #{limit}

SELECT COALESCE(view_count, 0)
FROM activity
WHERE id = #{id}

SELECT a.publish_status, a.lifecycle_status, a.id, a.title, a.summary, a.category, a.organizer, a.location, a.audience_scope, COALESCE(enrollment.subscriber_count, 0) AS subscriber_count, a.capacity, a.view_count, a.updated_at FROM ( SELECT publish_status, lifecycle_status, id, title, summary, category, organizer, location, audience_scope, capacity, view_count, updated_at FROM activity WHERE deleted_at IS NULL
AND (
id = #{keywordId} OR
MATCH(title, summary, organizer) AGAINST(#{keyword} IN BOOLEAN MODE) )
) a LEFT JOIN ( SELECT activity_id, COUNT(*) AS subscriber_count FROM activity_enrollment WHERE status = 1 GROUP BY activity_id ) enrollment ON enrollment.activity_id = a.id WHERE 1 = 1
AND a.publish_status = #{publishStatus}
AND a.lifecycle_status = #{lifecycleStatus}
ORDER BY a.updated_at DESC, a.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM activity
WHERE deleted_at IS NULL

    AND publish_status = #{publishStatus}


    AND lifecycle_status = #{lifecycleStatus}


    AND (

            id = #{keywordId} OR

        MATCH(title, summary, organizer) AGAINST(#{keyword} IN BOOLEAN MODE)
    )

mapper.update:
UPDATE activity
SET view_count = COALESCE(view_count, 0) + #{delta}
WHERE id = #{id}

UPDATE activity
SET form_version = #{formVersion}
WHERE id = #{id} AND form_version IS NULL AND deleted_at IS NULL

